mapper.select:
SELECT APPROVE_CNT, APPROVE_AMOUNT, FAIL_CNT, CANCEL_CNT,
ROUND( CASE WHEN APPROVE_CNT > 0 THEN FAIL_CNT / APPROVE_CNT END * 100 ,1) AS FAIL_RATE,
ROUND( CASE WHEN APPROVE_CNT > 0 THEN CANCEL_CNT / APPROVE_CNT END * 100 ,1) AS CANCEL_RATE
FROM ( SELECT SUM( CASE WHEN PAY_STATUS = 'APPROVE' THEN TOT_CNT ELSE 0 END ) AS APPROVE_CNT,
SUM( CASE WHEN PAY_STATUS = 'APPROVE' THEN TOT_AMOUNT ELSE 0 END ) AS APPROVE_AMOUNT,
SUM( CASE WHEN PAY_STATUS = 'FAIL' THEN TOT_CNT ELSE 0 END ) AS FAIL_CNT,
SUM( CASE WHEN PAY_STATUS = 'CANCEL' THEN TOT_CNT ELSE 0 END ) AS CANCEL_CNT
FROM AGG_PAYMENT_DAILY WHERE 1=1
AND BASE_DATE >= #{dto.baseDateFrom}
AND BASE_DATE <= #{dto.baseDateTo}
AND MERCHANT_ID = #{dto.merchantId}
AND PAY_METHOD = #{dto.payMethod}
AND PAY_STATUS = #{dto.payStatus}
)

SELECT BASE_DATE, MERCHANT_ID, PAY_METHOD,
SUM( CASE WHEN PAY_STATUS = 'APPROVE' THEN TOT_CNT ELSE 0 END ) AS APPROVE_CNT,
SUM( CASE WHEN PAY_STATUS = 'FAIL' THEN TOT_CNT ELSE 0 END ) AS FAIL_CNT,
SUM( CASE WHEN PAY_STATUS = 'CANCEL' THEN TOT_CNT ELSE 0 END ) AS CANCEL_CNT,
SUM( CASE WHEN PAY_STATUS = 'APPROVE' THEN TOT_AMOUNT
WHEN PAY_STATUS = 'CANCEL' THEN TOT_AMOUNT * -1
ELSE 0 END ) AS APPROVE_AMOUNT
FROM AGG_PAYMENT_DAILY WHERE 1=1
AND BASE_DATE >= #{dto.baseDateFrom}
AND BASE_DATE <= #{dto.baseDateTo}
AND MERCHANT_ID = #{dto.merchantId}
AND PAY_METHOD = #{dto.payMethod}
AND PAY_STATUS = #{dto.payStatus}
GROUP BY BASE_DATE, MERCHANT_ID, PAY_METHOD
ORDER BY BASE_DATE, MERCHANT_ID, PAY_METHOD
OFFSET #{dto.offset} ROWS FETCH NEXT #{dto.size} ROWS ONLY

SELECT COUNT(*)
FROM (
SELECT
BASE_DATE,
MERCHANT_ID,
PAY_METHOD
FROM AGG_PAYMENT_DAILY
WHERE 1=1


    AND BASE_DATE >= #{dto.baseDateFrom}



    AND BASE_DATE <= #{dto.baseDateTo}



    AND MERCHANT_ID = #{dto.merchantId}



    AND PAY_METHOD = #{dto.payMethod}



    AND PAY_STATUS = #{dto.payStatus}


GROUP BY
BASE_DATE,
MERCHANT_ID,
PAY_METHOD
)
